def exa_search(query, use_autoprompt=False, type="auto", start_published_date=None, end_published_date=None, 
               include_domains=None, exclude_domains=None, num_results=10, text=False, highlights=False):
    if not client_exa:
        return {"error": "Exa API key not configured"}

    try:
        cache_key = f"{query}_{type}_{start_published_date}_{end_published_date}_{num_results}"
        if cache_key in search_cache and time.time() - search_cache[cache_key]['timestamp'] < 3600:
            return search_cache[cache_key]['data']

        params = {
            "query": query,
            "use_autoprompt": use_autoprompt,
            "type": type,
            "num_results": num_results
        }

        if start_published_date:
            params["start_published_date"] = start_published_date
        if end_published_date:
            params["end_published_date"] = end_published_date
        if include_domains:
            params["include_domains"] = include_domains
        if exclude_domains:
            params["exclude_domains"] = exclude_domains
        if text:
            params["text"] = text
        if highlights:
            params["highlights"] = highlights

        results = client_exa.search(**params)

        cache_data = {
            "data": {
                "results": [
                    {
                        "title": r.title,
                        "url": r.url,
                        "score": r.score,
                        "published_date": r.published_date,
                        "domain": r.domain
                    } for r in results.results
                ]
            },
            "timestamp": time.time()
        }
        search_cache[cache_key] = cache_data
        return cache_data["data"]
    except Exception as e:
        return {"error": str(e)}

def exa_search_and_contents(query, use_autoprompt=False, type="auto", text_options=None, highlights_options=None, num_results=10):
    if not client_exa:
        return {"error": "Exa API key not configured"}

    try:
        results = client_exa.search_and_contents(
            query,
            use_autoprompt=use_autoprompt,
            type=type,
            num_results=num_results,
            text=text_options or {"max_characters": 2000},
            highlights=highlights_options
        )
        return {
            "results": [
                {
                    "title": r.title,
                    "url": r.url,
                    "score": r.score,
                    "text": getattr(r, 'text', '')[:500] + '...' if getattr(r, 'text', '') else '',
                    "highlights": [h.text for h in getattr(r, 'highlights', [])] if highlights_options else []
                } for r in results.results
            ]
        }
    except Exception as e:
        return {"error": str(e)}

def exa_find_similar(url, exclude_source_domain=False, text=False, num_results=10):
    if not client_exa:
        return {"error": "Exa API key not configured"}

    try:
        results = client_exa.find_similar(url, exclude_source_domain=exclude_source_domain, num_results=num_results, text=text)
        return {
            "results": [
                {
                    "title": r.title,
                    "url": r.url,
                    "score": r.score,
                    "text": getattr(r, 'text', '')[:500] + '...' if text and getattr(r, 'text', '') else ''
                } for r in results.results
            ]
        }
    except Exception as e:
        return {"error": str(e)}

def exa_answer(query, text=False):
    if not client_exa:
        return {"error": "Exa API key not configured"}

    try:
        response = client_exa.answer(query, text=text)
        return {
            "answer": response.answer,
            "citations": [
                {
                    "title": c.title,
                    "url": c.url,
                    "snippet": c.snippet
                } for c in getattr(response, 'citations', [])
            ] if hasattr(response, 'citations') else []
        }
    except Exception as e:
        return {"error": str(e)}

